'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { supabaseClient } from '@/lib/supabaseClient';
import Link from 'next/link';
import Loader from '@/components/Loader';

export default function SignupPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [signupLoading, setSignupLoading] = useState(false);
  const router = useRouter();

  const handleSignup = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSignupLoading(true);
    const { data, error } = await supabaseClient.auth.signUp({ email, password });
    if (error) { setError(error.message); } 
    else { alert("Check your email for the confirmation link!"); router.push('/login'); }
    setSignupLoading(false);
  };

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center custom-img p-4">
      <div className="absolute inset-0 bg-red-950/50 backdrop-blur-md z-10" />
      <div className="relative z-20 w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden">
        <div className="bg-red-700 py-8 text-center text-white">
          <h2 className="text-3xl font-black uppercase tracking-tighter">Create Account</h2>
          <p className="text-red-100 text-sm opacity-80">Join the Westgate Sindjelic Family</p>
        </div>
        <form className="p-8 space-y-6" onSubmit={handleSignup}>
          <input type="email" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)} 
                 className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-red-600 transition" required />
          <input type="password" placeholder="Choose Password" value={password} onChange={(e) => setPassword(e.target.value)} 
                 className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg outline-none focus:ring-2 focus:ring-red-600 transition" required />
          <button type="submit" className="w-full py-4 bg-red-600 text-white font-black uppercase tracking-widest rounded-lg hover:bg-red-700 transition shadow-lg shadow-red-600/20">
            {signupLoading ? <Loader /> : 'Sign Up'}
          </button>
          {error && <p className="text-red-600 text-center text-xs font-bold">{error}</p>}
          <p className="text-center text-sm text-gray-500">
            Already have an account? <Link href="/login" className="text-red-700 font-bold hover:underline">Sign in</Link>
          </p>
        </form>
      </div>
    </div>
  );
}